use gamepkg::{audio_voices::EffectCommand, runtime::Game};
use std::sync::{Arc, Mutex};

#[test]
#[ignore = "requires private signed fixtures generated by tools/check_effect_sdk.py"]
fn signed_generated_effect_bindings_commit_in_native_core_and_component() {
    let root = std::path::PathBuf::from(std::env::var_os("GAMEPKG_EFFECT_SDK_LIBRARY").unwrap());
    let native = std::env::var_os("GAMEPKG_EFFECT_SDK_NATIVE").is_some();
    for suffix in ["core", "component"] {
        for enabled in [false, true] {
            let id = format!(
                "com.gamepkg.effects-{suffix}-{}",
                if enabled { "on" } else { "off" }
            );
            let mut game =
                Game::load_target(&root, &id, &[], Some(native && suffix == "core")).unwrap();
            let batches = Arc::new(Mutex::new(Vec::new()));
            let target = batches.clone();
            game.attach_effect_output(Arc::new(move |commands| {
                target.lock().unwrap().push(commands.to_vec());
                true
            }));
            assert_eq!(
                game.step(0).unwrap(),
                if enabled { 1033 } else { 874 },
                "{id}"
            );
            {
                let batches = batches.lock().unwrap();
                assert_eq!(batches.len(), usize::from(enabled));
                if enabled {
                    assert_eq!(batches[0].len(), 5);
                    assert!(matches!(batches[0][0], EffectCommand::Volume(64)));
                    assert!(matches!(batches[0][1], EffectCommand::Pause(false)));
                    assert!(matches!(batches[0][3], EffectCommand::Stop));
                    let (EffectCommand::Play(first), EffectCommand::Play(second)) =
                        (&batches[0][2], &batches[0][4])
                    else {
                        panic!("missing signed effect")
                    };
                    assert!(Arc::ptr_eq(first, second));
                    let mut mixer = gamepkg::audio_voices::Mixer::default();
                    mixer.play(first.clone());
                    for _ in 0..4096 {
                        assert_eq!(mixer.frame([0; 2]), [12345, -23456]);
                    }
                    assert_eq!(mixer.active(), 0);
                }
            }
            batches.lock().unwrap().clear();
            assert!(
                game.step(1).is_err(),
                "fixture must trap after staging: {id}"
            );
            assert!(
                batches.lock().unwrap().is_empty(),
                "failed tick emitted effects: {id}"
            );
            drop(game);
            if enabled {
                for failure in ["save", "history", "output"] {
                    let mut game =
                        Game::load_target(&root, &id, &[], Some(native && suffix == "core"))
                            .unwrap();
                    let delivered = Arc::new(Mutex::new(0usize));
                    let target = delivered.clone();
                    game.attach_effect_output(Arc::new(move |_| {
                        *target.lock().unwrap() += 1;
                        true
                    }));
                    assert_eq!(game.step(0).unwrap(), 1033);
                    *delivered.lock().unwrap() = 0;
                    let directory = match failure {
                        "save" => Some("saves"),
                        "history" => Some("progress"),
                        _ => None,
                    };
                    if let Some(directory) = directory {
                        std::fs::rename(
                            root.join(directory),
                            root.join(format!("old-{directory}")),
                        )
                        .unwrap();
                        std::fs::write(root.join(directory), b"blocked").unwrap();
                    } else {
                        game.attach_effect_output(Arc::new(|_| false));
                    }
                    assert!(
                        game.step(2).is_err(),
                        "{id}: {failure} did not reject effects"
                    );
                    assert_eq!(
                        *delivered.lock().unwrap(),
                        0,
                        "{id}: {failure} emitted effects"
                    );
                    drop(game);
                    if let Some(directory) = directory {
                        std::fs::remove_file(root.join(directory)).unwrap();
                        std::fs::rename(
                            root.join(format!("old-{directory}")),
                            root.join(directory),
                        )
                        .unwrap();
                    }
                }
            }
            #[cfg(feature = "audio")]
            if enabled {
                assert!(std::env::var_os("ALSA_CONFIG_PATH").is_some());
                let mut game =
                    Game::load_target(&root, &id, &[], Some(native && suffix == "core")).unwrap();
                let audio = gamepkg::audio::Player::new(100).unwrap();
                assert!(audio.original_source(game.effect_playback().unwrap()));
                game.attach_effect_output(audio.effect_publisher());
                assert_eq!(game.step(0).unwrap(), 1033);
                let start = std::time::Instant::now();
                while audio.non_silent_frames() < 4096 {
                    assert!(start.elapsed() < std::time::Duration::from_secs(5));
                    std::thread::sleep(std::time::Duration::from_millis(1));
                }
                std::thread::sleep(std::time::Duration::from_millis(20));
                let audible = audio.non_silent_frames();
                assert!(game.step(1).is_err());
                std::thread::sleep(std::time::Duration::from_millis(20));
                assert_eq!(
                    audio.non_silent_frames(),
                    audible,
                    "failed tick replayed on the actual device: {id}"
                );
                assert!(audio.error().is_none());
                println!("Actual signed effect callback: {id}, native={}, audio advances without more game ticks and trap cannot replay", native && suffix == "core");
            }
            println!(
                "Signed generated effect bindings: {id}, successful batch then failed-tick denial"
            );
        }
    }
}
